"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Dialog, DialogActions, DialogClose, DialogSurface, DialogTrigger, useDialog } from "@/components/ui/dialog"

/** A page slid in from the edge. Same props and behaviour as Dialog: the native <dialog> keeps focus, Escape and the top layer. */
const Sheet = Dialog
const SheetTrigger = DialogTrigger
const SheetClose = DialogClose

type SheetContentProps = React.ComponentProps<"dialog"> & {
  /** Which edge it slides from. Logical, so start is the right edge in right-to-left. */
  side?: "start" | "end" | "top" | "bottom"
}

function SheetContent({ className, side = "end", ...props }: SheetContentProps) {
  return <DialogSurface data-slot="sheet-content" data-side={side} className={cn("db-sheet", className)} {...props} />
}

/** The sheet's name, running up its spine like a book's. Decorative: the visible title is SheetTitle. */
function SheetSpine({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="sheet-spine" aria-hidden="true" className={cn("db-sheet-spine", className)} {...props} />
}

function SheetTitle({ className, ...props }: React.ComponentProps<"h2">) {
  const { titleId } = useDialog()
  return <h2 data-slot="sheet-title" id={titleId} className={cn("db-sheet-title", className)} {...props} />
}

function SheetDescription({ className, ...props }: React.ComponentProps<"p">) {
  const { descriptionId } = useDialog()
  return <p data-slot="sheet-description" id={descriptionId} className={cn("db-sheet-body", className)} {...props} />
}

function SheetActions(props: React.ComponentProps<"div">) {
  return <DialogActions data-slot="sheet-actions" {...props} />
}

export { Sheet, SheetTrigger, SheetContent, SheetSpine, SheetTitle, SheetDescription, SheetActions, SheetActions as SheetFooter, SheetClose }

@layer components {
  /* ── db-sheet ── a page slid in from the edge; its title runs up the spine.
     The backdrop lives in dialog.css. Sides are logical: start and end follow
     the reading direction, so the sheet meets the right edge in right-to-left. */
  .db-sheet {
    --from: 100% 0; /* where it waits, off the edge it comes from */
    position: fixed; inset-block: 0; inset-inline: auto 0; margin: 0; width: min(32rem, calc(100vw - var(--db-space-6))); height: 100dvh; max-width: none; max-height: none;
    padding-block: var(--db-space-7) var(--db-space-6); padding-inline: var(--db-space-8) var(--db-space-6); overflow: auto;
    border: 0; border-inline-start: var(--db-hairline) solid var(--db-ink); background: var(--db-paper); color: var(--db-graphite);
    translate: var(--from);
    transition: translate var(--db-andante) var(--db-exhale), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  .db-sheet[open] { translate: 0 0; }
  @starting-style { .db-sheet[open] { translate: var(--from); } }
  .db-sheet:is([dir="rtl"], [dir="rtl"] *) { --from: -100% 0; }
  .db-sheet[data-side="start"] { --from: -100% 0; inset-inline: 0 auto; border-inline-start: 0; border-inline-end: var(--db-hairline) solid var(--db-ink); }
  .db-sheet[data-side="start"]:is([dir="rtl"], [dir="rtl"] *) { --from: 100% 0; }
  .db-sheet:is([data-side="top"], [data-side="bottom"]) { inset-inline: 0; width: 100%; height: auto; max-height: 85dvh; border-inline-start: 0; }
  .db-sheet[data-side="top"] { --from: 0 -100%; inset-block: 0 auto; border-block-end: var(--db-hairline) solid var(--db-ink); }
  .db-sheet[data-side="bottom"] { --from: 0 100%; inset-block: auto 0; border-block-start: var(--db-hairline) solid var(--db-ink); }
  /* left and right, not inset-inline-start: in the spine's own vertical writing mode that means top,
     and the spine fell into the text. The sheet's space-8 inline-start padding is its column. */
  .db-sheet-spine {
    position: absolute; left: var(--db-space-4); bottom: var(--db-space-6);
    writing-mode: vertical-rl; rotate: 180deg; white-space: nowrap;
    font-size: var(--db-f); line-height: 1; letter-spacing: var(--db-f-tr); font-weight: 200; color: var(--db-ink);
  }
  .db-sheet-spine:is([dir="rtl"], [dir="rtl"] *) { left: auto; right: var(--db-space-4); }
  .db-sheet[open] .db-sheet-spine { animation: db-spine var(--db-andante) var(--db-exhale) 240ms backwards; }
  @keyframes db-spine { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0); } }
  .db-sheet > * + *:not(.db-scrollbar) { margin-block-start: var(--db-space-6); }
  .db-sheet-title { font-size: var(--db-mf); line-height: var(--db-mf-lh); letter-spacing: var(--db-mf-tr); font-weight: 300; color: var(--db-ink); }
  .db-sheet-body { max-width: 40ch; }
}
